import csv
import sys
from collections import Counter


def count_non_empty_values(path):
    counts = Counter()
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        headers = next(reader, None)
        if not headers:
            return headers, counts
        for row in reader:
            for i, cell in enumerate(row):
                if i < len(headers) and cell.strip():
                    counts[headers[i]] += 1
    return headers, counts


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <csv_file>")
        sys.exit(1)
    headers, counts = count_non_empty_values(sys.argv[1])
    if not headers:
        print("Empty CSV file")
        return
    for name in headers:
        print(f"{name}: {counts[name]}")


if __name__ == "__main__":
    main()
